namespace CubeGame.Content
{
    /// <summary>
    /// Alpha creature size per kind (M0-F2B): the combat box of <c>GameController_updateSubsystems</c>'s projectile hit
    /// test. Table generated by <c>tools/alpha_content/gen_creature_sizes.py</c> from the emulated
    /// <c>creature_generateAppearance</c> (ALPHA_CODE_STATIC). Alpha axes are (x, y, z = up); <see cref="TryGet"/> returns
    /// Unity axes (width X, height Y, depth Z).
    /// </summary>
    public static partial class AlphaCreatureSizes
    {
        public static int Count => Sizes.Count;

        public static bool TryGet(int kind, out double width, out double height, out double depth)
        {
            if (Sizes.TryGetValue(kind, out float[] size))
            {
                width = size[0];
                depth = size[1];
                height = size[2];
                return true;
            }

            width = height = depth = 0.0;
            return false;
        }

        /// <summary>Kind whose placement scale is 1 in Unity (HumanMale, the reference body of the world model scale).</summary>
        public const int ReferenceKind = 0x02;

        /// <summary>
        /// Species scale (M0-F2B, EMULATED_ALPHA_CODE): <c>Creature_drawModel</c> multiplies every part by the creature
        /// placement matrix, whose uniform scale depends on the kind; the S05 capture divides it out, so the Unity model of
        /// any creature — hero or NPC — is drawn at <c>placement(kind) / placement(0x02)</c> of the world model scale.
        /// False (factor 1) for a kind without an emulated placement.
        /// </summary>
        public static bool TryGetSpeciesScale(int kind, out float factor)
        {
            factor = 1f;
            if (!Sizes.TryGetValue(kind, out float[] size) || size.Length < 4 || !Sizes.TryGetValue(ReferenceKind, out float[] reference))
            {
                return false;
            }

            factor = size[3] / reference[3];
            return true;
        }
    }
}
